    const { translateFields, isTranslating } = useAutoTranslate(formik);
    const [searchParams, setSearchParams] = useSearchParams();

    const isEditMode = type !== 'create';

    // Debug logging for categoryIds
    useEffect(() => {
        console.log('ProductForm - initialData.categoryIds:', initialData?.categoryIds);
        console.log('ProductForm - formik.values.categoryIds:', formik.values.categoryIds);
    }, [initialData?.categoryIds, formik.values.categoryIds]);

    // === БАЗОВИЙ URL ДЛЯ КАРТИНОК ===
    const API_BASE_URL = process.env.REACT_APP_API_URL_IMG?.trim() || process.env.REACT_APP_API_URL_IMG?.trim() || '';

    // Функція, яка підклеює домен до відносного шляху (якщо це ще не зроблено)
    const getFullImageUrl = (imgUrl) => {
        if (!imgUrl) return '';
        if (imgUrl.startsWith('http')) return imgUrl;
        return `${API_BASE_URL}${imgUrl}`;
    };

    // === СТЕЙТ ДЛЯ КАТЕГОРІЙ ===
    const [categoryOptions, setCategoryOptions] = useState([]);
    const [categoryMetaById, setCategoryMetaById] = useState({});
    const [accessoryCategoryIds, setAccessoryCategoryIds] = useState([]);
    const [accessorySearchQuery, setAccessorySearchQuery] = useState('');
    const [debouncedAccessorySearchQuery, setDebouncedAccessorySearchQuery] = useState('');
    const [accessoryOptions, setAccessoryOptions] = useState([{ value: '', label: 'Без аксесуара' }]);
    const [isAccessorySearchLoading, setIsAccessorySearchLoading] = useState(false);

    // === ЗАВАНТАЖЕННЯ ТА ФОРМАТУВАННЯ КАТЕГОРІЙ ===
    useEffect(() => {
        const fetchCategories = async () => {
            try {
                const treeData = await getAdminCategoriesTree();

                const categoriesArray = treeData?.items || treeData?.data || (Array.isArray(treeData) ? treeData : []);

                const categoryMap = {};
                const formattedOptions = [];
                const accessoryIds = [];

                const walkTree = (nodes, depth = 0) => {
                    nodes.forEach((cat) => {
                        const categoryId = String(cat._id || cat.id || '');
                        if (!categoryId) return;

                        const title = cat.title?.ua || cat.name?.ua || cat.title || 'Без назви';
                        const titleEn = cat.title?.en || cat.name?.en || '';

                        if (ACCESSORY_CATEGORY_PATTERN.test(`${title} ${titleEn}`)) {
                            accessoryIds.push(categoryId);
                        }

                        formattedOptions.push({
                            value: categoryId,
                            label: `${'— '.repeat(depth)}${title}`,
                        });

                        categoryMap[categoryId] = {
                            variationTemplate: Array.isArray(cat.variationTemplate) ? cat.variationTemplate : [],
                            rootVariationTemplate: Array.isArray(cat.rootVariationTemplate) ? cat.rootVariationTemplate : [],
                            isVariationTemplateOwner: Boolean(cat.isVariationTemplateOwner),
                        };

                        walkTree(cat.children || [], depth + 1);
                    });
                };

                walkTree(categoriesArray);

                setCategoryOptions(formattedOptions);
                setCategoryMetaById(categoryMap);
                setAccessoryCategoryIds([...new Set(accessoryIds)]);
                console.log('Category options loaded:', formattedOptions);
            } catch (error) {
                console.error("Помилка завантаження категорій:", error);
            }
        };

        fetchCategories();
    }, []);

    useEffect(() => {
        const selectedCategoryId = formik.values.categoryIds?.[0] || '';
        const selectedCategoryMeta = categoryMetaById[selectedCategoryId];

        if (!selectedCategoryId || !selectedCategoryMeta) return;

        const rawAxes = selectedCategoryMeta.rootVariationTemplate?.length
            ? selectedCategoryMeta.rootVariationTemplate
            : selectedCategoryMeta.variationTemplate || [];

        const normalizedAxes = buildEffectiveVariationAxes({
            initialData,
            variationsData,
            categoryAxes: Array.isArray(rawAxes) ? rawAxes : [],
        });

        const prevAxes = formik.values.variationAxes || [];
        if (JSON.stringify(prevAxes) !== JSON.stringify(normalizedAxes)) {
            formik.setFieldValue('variationAxes', normalizedAxes);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [formik.values.categoryIds, categoryMetaById, initialData, variationsData]);

const axes = formik.values.variationAxes || [];
const offers = formik.values.offers || [];

useEffect(() => {
    const timeoutId = setTimeout(() => {
        setDebouncedAccessorySearchQuery(accessorySearchQuery.trim());
    }, 450);

    return () => clearTimeout(timeoutId);
}, [accessorySearchQuery]);

useEffect(() => {
    let isCancelled = false;
    const loadAccessoryOptions = async () => {
        const nextOptionsMap = new Map();
        nextOptionsMap.set('', 'Без аксесуара');

        const addOption = (value, label) => {
            const normalizedValue = String(value || '').trim();
            if (!normalizedValue) return;
            if (!nextOptionsMap.has(normalizedValue)) {
                nextOptionsMap.set(normalizedValue, label || normalizedValue);
            }
        };

        if (!accessoryCategoryIds.length) {
            if (!isCancelled) {
                setAccessoryOptions(Array.from(nextOptionsMap, ([value, label]) => ({ value, label })));
            }
            return;
        }

        if (!isCancelled) setIsAccessorySearchLoading(true);
        try {
            const groupsById = new Map();

            await Promise.all(
                accessoryCategoryIds.map(async (categoryId) => {
                    const groupsResult = await getAdminCatalogGroups({
                        page: 1,
                        limit: 8,
                        categoryId,
                        q: debouncedAccessorySearchQuery || undefined,
                    });

                    const groups = groupsResult?.items || [];
                    groups.forEach((group) => {
                        const groupId = String(group?._id || '');
                        if (!groupId || groupsById.has(groupId)) return;
                        groupsById.set(groupId, group);
                    });
                })
            );

            const groups = Array.from(groupsById.values());
            await Promise.all(
                groups.map(async (group) => {
                    const groupId = String(group?._id || '');
                    if (!groupId) return;

                    const offersResult = await getAdminCatalogGroupVariationById(groupId, {
                        page: 1,
                        limit: 20,
                        q: debouncedAccessorySearchQuery || undefined,
                    });

                    const offerItems = offersResult?.items || offersResult?.item?.offers || [];
                    offerItems.forEach((offer) => {
                        const offerId = String(offer?._id || '');
                        if (!offerId) return;

                        addOption(offerId, getAccessoryOptionLabel({
                            offer,
                            productGroup: group,
                            offerId,
                        }));
                    });
                })
            );

            if (!isCancelled) {
                setAccessoryOptions(Array.from(nextOptionsMap, ([value, label]) => ({ value, label })));
            }
        } catch (error) {
            console.error('Помилка пошуку аксесуарів:', error);
            if (!isCancelled) {
                setAccessoryOptions(Array.from(nextOptionsMap, ([value, label]) => ({ value, label })));
            }
        } finally {
            if (!isCancelled) setIsAccessorySearchLoading(false);
        }
    };

    loadAccessoryOptions();
    return () => {
        isCancelled = true;
    };
}, [accessoryCategoryIds, debouncedAccessorySearchQuery]);

useEffect(() => {
    setAccessoryOptions((prevOptions) => {
        const optionMap = new Map(prevOptions.map((option) => [String(option.value || ''), option.label]));
        optionMap.set('', 'Без аксесуара');

        offers.forEach((offer) => {
            const accessoryOfferId = normalizeAccessoryOfferId(offer);
            if (!accessoryOfferId) return;

            if (optionMap.has(accessoryOfferId)) return;

            const firstAccessory = Array.isArray(offer?.accessories) ? offer.accessories[0] : null;
            optionMap.set(accessoryOfferId, getAccessoryOptionLabel(firstAccessory || { offerId: accessoryOfferId }));
        });

        return Array.from(optionMap, ([value, label]) => ({ value, label }));
    });
}, [offers]);

useEffect(() => {
    const accessoryIds = offers
        .map((offer) => normalizeAccessoryOfferId(offer))
        .filter(Boolean);

    const nextGroupAccessoryValue = accessoryIds.length
        ? ([...new Set(accessoryIds)].length === 1 ? accessoryIds[0] : '')
        : '';

    if ((formik.values.groupAccessoryOfferId || '') !== nextGroupAccessoryValue) {
        formik.setFieldValue('groupAccessoryOfferId', nextGroupAccessoryValue, false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
