const handleApplyAccessoryToAllOffers = (accessoryOfferId) => {
    const normalizedAccessoryOfferId = String(accessoryOfferId || '').trim();
    formik.setFieldValue('groupAccessoryOfferId', normalizedAccessoryOfferId);

    const nextOffers = (formik.values.offers || []).map((offer) => ({
        ...offer,
        accessoryOfferId: normalizedAccessoryOfferId,
    }));

    formik.setFieldValue('offers', nextOffers);
};

const axisHasValues = (axisId) => {
    if (!axisId) return false;

    return offers.some((offer) => {
        const axisValue = offer?.options?.[axisId];
        return String(axisValue ?? '').trim() !== '';
    });
};

const pickImageVariantAxis = () => {
    if (!axes.length) return null;

    const prioritizedAxisIds = ['A4', 'A3', 'A5', 'A1'];

    for (const axisId of prioritizedAxisIds) {
        const axis = axes.find((item) => String(item?.axisId) === axisId);
        if (axis && axisHasValues(axisId)) {
            return axis;
        }
    }

    return axes[axes.length - 2] || axes[axes.length - 1] || null;
};

const imageVariantAxis = pickImageVariantAxis();
const imageSyncAxes = imageVariantAxis
    ? axes.filter((axis) => axis?.axisId && axis.axisId !== imageVariantAxis.axisId)
    : [];

const imageSyncAxesKey = imageSyncAxes.map((axis) => axis.axisId).join('|');

const getOfferImageClusterKey = (offer) => {
    if (!imageVariantAxis) return '';
    if (!imageSyncAxes.length) return '__all_last_axis_values__';

    const keyParts = [];

    for (const axis of imageSyncAxes) {
        const axisValue = String(offer?.options?.[axis.axisId] || '').trim();
        if (!axisValue) continue;
        keyParts.push(`${axis.axisId}:${axisValue}`);
    }

    if (!keyParts.length) return '';

    return keyParts.join('|');
};

const getClusterImage = (sourceOffers = [], clusterKey, excludedIndex = -1) => {
    if (!clusterKey) return '';

    const matchedOffer = sourceOffers.find((offer, index) => {
        if (index === excludedIndex) return false;

        const image = typeof offer?.image === 'string' ? offer.image.trim() : '';
        if (!image) return false;

        return getOfferImageClusterKey(offer) === clusterKey;
    });

    return typeof matchedOffer?.image === 'string' ? matchedOffer.image.trim() : '';
};

const syncOfferImagesForDisplay = (sourceOffers = []) => {
    if (!Array.isArray(sourceOffers) || !sourceOffers.length || !imageVariantAxis) {
        return sourceOffers;
    }

    const imageByCluster = new Map();

    sourceOffers.forEach((offer) => {
        const image = typeof offer?.image === 'string' ? offer.image.trim() : '';
        if (!image) return;

        const clusterKey = getOfferImageClusterKey(offer);
        if (!clusterKey) return;

        if (!imageByCluster.has(clusterKey)) {
            imageByCluster.set(clusterKey, image);
        }
    });

    if (!imageByCluster.size) return sourceOffers;

    return sourceOffers.map((offer) => {
        const currentImage = typeof offer?.image === 'string' ? offer.image.trim() : '';
        if (currentImage) return offer;

        const clusterKey = getOfferImageClusterKey(offer);
        const sharedImage = imageByCluster.get(clusterKey);
        if (!sharedImage) return offer;

        return {
            ...offer,
            image: sharedImage,
        };
    });
};

const setOfferImageWithAxisSync = (offerIndex, nextImage) => {
    const sourceOffer = formik.values.offers?.[offerIndex];
    if (!sourceOffer) return;

    const normalizedImage = typeof nextImage === 'string' ? nextImage.trim() : '';
    const clusterKey = getOfferImageClusterKey(sourceOffer);

    if (!imageVariantAxis || !clusterKey) {
        formik.setFieldValue(`offers[${offerIndex}].image`, normalizedImage);
        return;
    }

    const nextOffers = (formik.values.offers || []).map((offer, index) => {
        if (index === offerIndex) {
            return {
                ...offer,
                image: normalizedImage,
            };
        }

        const isSameAxisCluster = getOfferImageClusterKey(offer) === clusterKey;

        if (!isSameAxisCluster) {
            return offer;
        }

        return {
            ...offer,
            image: normalizedImage,
        };
    });

    formik.setFieldValue('offers', nextOffers);
};

const handleOfferOptionChange = (offerIndex, axisId, value) => {
    const currentOffers = formik.values.offers || [];
    const sourceOffer = currentOffers[offerIndex];

    if (!sourceOffer) return;

    const nextOffers = currentOffers.map((offer, index) => {
        if (index !== offerIndex) return offer;

        return {
            ...offer,
            options: {
                ...(offer?.options || {}),
                [axisId]: value,
            },
        };
    });

    if (!imageVariantAxis) {
        formik.setFieldValue('offers', nextOffers);
        return;
    }

    const nextOffer = nextOffers[offerIndex];
    const targetClusterKey = getOfferImageClusterKey(nextOffer);
    const targetClusterImage = getClusterImage(nextOffers, targetClusterKey, offerIndex);
    const nextOfferImage = typeof nextOffer?.image === 'string' ? nextOffer.image.trim() : '';
    const clusterImageToApply = targetClusterImage || nextOfferImage;

    if (!clusterImageToApply) {
        formik.setFieldValue('offers', nextOffers);
        return;
    }

    const syncedOffers = nextOffers.map((offer) => {
        if (getOfferImageClusterKey(offer) !== targetClusterKey) {
            return offer;
        }

        return {
            ...offer,
            image: clusterImageToApply,
        };
    });

    formik.setFieldValue('offers', syncedOffers);
};

useEffect(() => {
    if (!imageVariantAxis || !offers.length) return;

    const syncedOffers = syncOfferImagesForDisplay(offers);
    if (JSON.stringify(syncedOffers) !== JSON.stringify(offers)) {
        formik.setFieldValue('offers', syncedOffers, false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
}, [offers, imageVariantAxis?.axisId, imageSyncAxesKey]);

const selectableAxes = useMemo(
